"""Registry of samples by batch."""

_ALL = []
_BY_KEY = None


def reset():
    """Forget every registered sample."""
    global _BY_KEY
    del _ALL[:]
    _BY_KEY = None


def register(sample):
    """Add one sample to the registry."""
    _ALL.append(sample)


def find(batch):
    """Return the samples registered under this batch."""
    global _BY_KEY
    if _BY_KEY is None:
        _BY_KEY = {}
        for x in _ALL:
            _BY_KEY.setdefault(x.batch, []).append(x)
    return _BY_KEY.get(batch, [])

